CREATE OR REPLACE FUNCTION public.pm_verify_week_publication() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE ba text;be text;bs text;bn text;bp text;rid uuid;pid uuid;sid uuid;aid uuid;protected uuid;planid uuid;pubid uuid:=gen_random_uuid();preview jsonb;result jsonb;n integer;checks integer:=0;
BEGIN
SELECT md5(string_agg(to_jsonb(a)::text,'|' ORDER BY id)) INTO ba FROM pm_allocations a;
SELECT md5(string_agg(to_jsonb(e)::text,'|' ORDER BY id)) INTO be FROM pm_time_entries e;
SELECT md5(string_agg(to_jsonb(e)::text,'|' ORDER BY id)) INTO bs FROM pm_stages e;
SELECT md5(string_agg(to_jsonb(e)::text,'|' ORDER BY id)) INTO bn FROM notifications e;
SELECT md5(string_agg(to_jsonb(e)::text,'|' ORDER BY id)) INTO bp FROM pm_cost_rate_periods e;
BEGIN
PERFORM set_config('request.jwt.claims','{"sub":"ab5a48c0-939b-4502-bd3b-db7801f0f8b8","role":"authenticated"}',true);
PERFORM set_config('request.jwt.claim.sub','ab5a48c0-939b-4502-bd3b-db7801f0f8b8',true);
INSERT INTO pm_resources(name,weekly_capacity,active) VALUES('ROLLBACK publication fixture',40,true) RETURNING id INTO rid;
INSERT INTO pm_projects(name,start_date) VALUES('ROLLBACK publication fixture','2099-01-01') RETURNING id INTO pid;
INSERT INTO pm_stages(project_id,name,start_date,end_date) VALUES(pid,'Fixture stage','2099-01-01','2099-02-28') RETURNING id INTO sid;
INSERT INTO pm_allocations(stage_id,resource_id,start_date,end_date,hours_per_day,day_part,is_site_visit,source,allocation_percentage) VALUES(sid,rid,'2099-01-01','2099-01-31',2,'am',true,'manual',25) RETURNING id INTO aid;
INSERT INTO pm_tasks(allocation_id,name) VALUES(aid,'Task history must survive');
INSERT INTO pm_allocations(stage_id,resource_id,start_date,end_date,hours_per_day,day_part,is_locked,source) VALUES(sid,rid,'2099-01-12','2099-01-12',3,'am',true,'imported_accelo') RETURNING id INTO protected;
PERFORM pm_week_draft('2099-01-12','create','[]');
SELECT id INTO planid FROM pm_week_plans WHERE week_start='2099-01-12';
INSERT INTO pm_week_plan_slots(plan_id,resource_id,day,part,project_id,stage_id,is_site_visit) SELECT planid,rid,'2099-01-12',part,pid,sid,true FROM unnest(ARRAY['am','pm']) part;
preview:=pm_preview_week_plan(planid);
IF jsonb_array_length(preview->'offending_cells')<>0 OR jsonb_array_length(preview->'overlaps')<>1 OR jsonb_array_length(preview->'skipped')<>1 THEN RAISE EXCEPTION 'Preview protected checks failed'; END IF;
IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(preview->'operations') e WHERE e->>'action'='create' AND e->'after'->>'day_part'='full' AND (e->'after'->>'hours_per_day')::numeric=6 AND (e->'after'->>'is_site_visit')::boolean) THEN RAISE EXCEPTION 'Full-day capacity failed'; END IF;checks:=checks+1;
BEGIN PERFORM pm_apply_week_plan(planid,preview->>'token','[]',false,false,pubid);RAISE EXCEPTION 'Overlap accepted without acknowledgement';EXCEPTION WHEN OTHERS THEN IF SQLERRM<>'Protected overlap acknowledgement required' THEN RAISE;END IF;END;checks:=checks+1;
BEGIN PERFORM pm_apply_week_plan(planid,'stale','[]',true,false,pubid);RAISE EXCEPTION 'Stale preview accepted';EXCEPTION WHEN serialization_failure THEN NULL;END;checks:=checks+1;
BEGIN result:=pm_apply_week_plan(planid,preview->>'token','[]',true,false,pubid);RAISE EXCEPTION 'fixture_interruption';EXCEPTION WHEN OTHERS THEN IF SQLERRM<>'fixture_interruption' THEN RAISE;END IF;END;
IF (SELECT end_date FROM pm_allocations WHERE id=aid)<>'2099-01-31' OR EXISTS(SELECT 1 FROM pm_week_publications WHERE id=pubid) OR (SELECT status FROM pm_week_plans WHERE id=planid)<>'draft' THEN RAISE EXCEPTION 'Interrupted publication leaked';END IF;checks:=checks+1;
result:=pm_apply_week_plan(planid,preview->>'token','[]',true,false,pubid);
IF result->>'created'<>'2' OR result->>'changed'<>'1' OR result->>'removed'<>'0' THEN RAISE EXCEPTION 'Exact split/apply mismatch';END IF;
IF NOT EXISTS(SELECT 1 FROM pm_allocations WHERE resource_id=rid AND start_date='2099-01-19' AND end_date='2099-01-31' AND hours_per_day=2 AND source='manual' AND is_site_visit AND allocation_percentage=25) OR (SELECT end_date FROM pm_allocations WHERE id=aid)<>'2099-01-11' THEN RAISE EXCEPTION 'Outside metadata lost';END IF;
IF (SELECT is_locked FROM pm_allocations WHERE id=protected) IS NOT TRUE OR NOT EXISTS(SELECT 1 FROM pm_tasks WHERE allocation_id=aid) THEN RAISE EXCEPTION 'Protected/task preservation failed';END IF;checks:=checks+1;
SELECT count(*) INTO n FROM notifications WHERE entity_id=planid AND kind='week_plan_published';
IF n<>(SELECT count(DISTINCT u.id) FROM auth.users u JOIN collaborators c ON lower(c.email)=lower(u.email) WHERE c.archived_at IS NULL) THEN RAISE EXCEPTION 'Bell recipients mismatch';END IF;
PERFORM pm_apply_week_plan(planid,preview->>'token','[]',true,false,pubid);
IF n<>(SELECT count(*) FROM notifications WHERE entity_id=planid AND kind='week_plan_published') THEN RAISE EXCEPTION 'Retry duplicated bells';END IF;checks:=checks+1;
PERFORM pm_revise_week_plan(planid,(SELECT updated_at FROM pm_week_plans WHERE id=planid),(SELECT published_slots FROM pm_week_publications WHERE id=pubid));
preview:=pm_preview_week_plan(planid);
IF jsonb_array_length(preview->'operations')<>0 THEN RAISE EXCEPTION 'No-change revision changed allocations';END IF;
PERFORM pm_apply_week_plan(planid,preview->>'token','[]',true,false,gen_random_uuid());
IF n*2<>(SELECT count(*) FROM notifications WHERE entity_id=planid AND kind='week_plan_published') THEN RAISE EXCEPTION 'Deliberate publication bells missing';END IF;checks:=checks+1;
PERFORM pm_revise_week_plan(planid,(SELECT updated_at FROM pm_week_plans WHERE id=planid),'[]');
preview:=pm_preview_week_plan(planid);result:=pm_apply_week_plan(planid,preview->>'token','[]',false,false,gen_random_uuid());
IF result->>'removed'<>'1' THEN RAISE EXCEPTION 'Empty week did not remove allocation';END IF;
IF NOT EXISTS(SELECT 1 FROM pm_allocations WHERE resource_id=rid AND planning_removed_at IS NOT NULL) OR NOT EXISTS(SELECT 1 FROM pm_tasks WHERE allocation_id=aid) THEN RAISE EXCEPTION 'Retirement/task history failed';END IF;checks:=checks+1;
RAISE EXCEPTION 'verification_rollback';
EXCEPTION WHEN OTHERS THEN IF SQLERRM<>'verification_rollback' THEN RAISE;END IF;END;
IF ba IS DISTINCT FROM (SELECT md5(string_agg(to_jsonb(e)::text,'|' ORDER BY id)) FROM pm_allocations e) OR be IS DISTINCT FROM (SELECT md5(string_agg(to_jsonb(e)::text,'|' ORDER BY id)) FROM pm_time_entries e) OR bs IS DISTINCT FROM (SELECT md5(string_agg(to_jsonb(e)::text,'|' ORDER BY id)) FROM pm_stages e) OR bn IS DISTINCT FROM (SELECT md5(string_agg(to_jsonb(e)::text,'|' ORDER BY id)) FROM notifications e) OR bp IS DISTINCT FROM (SELECT md5(string_agg(to_jsonb(e)::text,'|' ORDER BY id)) FROM pm_cost_rate_periods e) THEN RAISE EXCEPTION 'Rolled-back test changed live rows';END IF;
RETURN jsonb_build_object('checks',checks,'rollback_verified',true,'allocations_unchanged',(SELECT count(*) FROM pm_allocations),'periods_unchanged',(SELECT count(*) FROM pm_cost_rate_periods),'entries_stages_notifications_unchanged',true);
END $$;
REVOKE ALL ON FUNCTION public.pm_verify_week_publication() FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.pm_verify_week_publication() TO service_role;